insert into public.campfire_days (series_id, season_number, week, day, data) values
('dark-moon', 1, 2, 1, '{"place":"The mine, then the mill road","narrated":false,"tone":"wry","cupNight":true,"opener":"Beds are in the barn tonight. Pick a corner and take it.","forkA":"They''re keeping Corin close, upriver.","forkB":"Upriver is only the road away.","callback":"The mine wall put Tamsin''s name first and Corin''s second. Tamsin heard them say \"the mill boy next\".","nudge":"{friend:Aim}, the cart turned upriver. How far do you think it went?","riddle":{"q":"I have a face and two hands but no arms or legs. What am I?","a":"a clock","quip":"Time''s the one thing the cart has on us.","accept":["a clock","clock"],"maxTries":3},"leads":[{"id":"2-1-1","place":"the bench by his door","actions":[{"attr":"Charm","verb":"let him tell it his own way"},{"attr":"Intellect","verb":"ask him about the horse, not the men"}],"clueTitle":"The steady horse","clueText":"The old man says the horse never balked at his gate or at the fork, in full dark and with no lamp. It took the mill lane at a steady walk.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-2","place":"the fresh ruts in the lane","actions":[{"attr":"Aim","verb":"follow the ruts past his gate"},{"attr":"Craft","verb":"read where the wheels ran"}],"clueTitle":"Past the gate","clueText":"The ruts run past his gate without a check. By that gate, in plain sight of the lane, a child''s wooden horse lies on its side in the grass.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-1-3","place":"where the cart turned upriver","actions":[{"attr":"Agility","verb":"run down to the turn before dark"},{"attr":"Aim","verb":"read the turn in the half-light"}],"clueTitle":"Deeper coming down","clueText":"Where the cart turned upriver, the ruts coming down sink deeper into the verge than the ruts going up.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"We held his last wall.\"* Whose wall, and why was it meant to fall?","weekQuestion":"Why these children, and not any others?","pull":"**The mill is an hour on. At first light: what did the family see?**"}'::jsonb),
('dark-moon', 1, 2, 2, '{"place":"The mill","narrated":false,"tone":"wry","cupNight":false,"opener":"Asked for by name, and by the night he was born. That''s an odd thing to ask for.","forkA":"They had a list with birthdays.","forkB":"They knew him personally.","callback":"In the mine, that shape was a hole, and what sat in it was gone. Here it''s cut into the mill''s footing.","nudge":"{friend:Craft}, how was the mark cut, and with what tool?","riddle":{"q":"I have teeth but cannot bite. What am I?","a":"a comb (or a cog)","quip":"A mill''s full of them.","accept":["a comb (or a cog)","comb (or a cog)"],"maxTries":3},"leads":[{"id":"2-2-1","place":"the doorway, with her","actions":[{"attr":"Charm","verb":"ask her what was in his hands"},{"attr":"Intellect","verb":"ask her what he did before he spoke"}],"clueTitle":"The paper in his fist","clueText":"She says he had a folded paper in his fist. He looked at it once, then said the boy''s name.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-2","place":"inside the mill door","actions":[{"attr":"Aim","verb":"follow his boot-marks inside"},{"attr":"Craft","verb":"read the dried mud on the boards"}],"clueTitle":"Straight to the bed","clueText":"Nobody has swept since. His dried boot-mud goes from the door straight to the boy''s bed and back, and never turns aside.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-2-3","place":"the yard where the cart stood","actions":[{"attr":"Aim","verb":"walk the yard by the light from the door"},{"attr":"Craft","verb":"read what the horse left behind"}],"clueTitle":"The cropped grass","clueText":"Where the cart stood in the yard, the grass is cropped short in a wide half-circle, as far as a tethered horse can reach.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"By the third, we had stopped.\"* Why stop counting?","weekQuestion":"Why these children, and not any others?","pull":"**Upriver. The ruts are four nights old, and there is weather coming.**"}'::jsonb),
('dark-moon', 1, 2, 3, '{"place":"Upriver","narrated":false,"tone":"wry","cupNight":false,"opener":"A stranger dead at a lock, and a lock that opened for you. Rooms like that have opinions.","forkA":"The stranger wanted the same door.","forkB":"The stranger was left as a warning.","callback":"Corin was asked for by name. Today a lock that wouldn''t open for a dead man opened for you.","nudge":"{friend:Intellect}, did that stranger die trying the lock, or was he left for us?","riddle":{"q":"What has many keys but opens no door?","a":"a piano","quip":"Not like that lock. It opened for you.","accept":["a piano","piano"],"maxTries":3},"leads":[{"id":"2-3-1","place":"the stone round the housing","actions":[{"attr":"Craft","verb":"look at the stone round the lock"},{"attr":"Intellect","verb":"read the marks cut into it"}],"clueTitle":"The scratches","clueText":"The stone round the housing is scored with dozens of short scratches, some weathered and some bright. He tried it more than once, on more than one day.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-2","place":"the stranger on the path","actions":[{"attr":"Charm","verb":"kneel by him and close his eyes"},{"attr":"Intellect","verb":"go through what he carried"}],"clueTitle":"Silver in his purse","clueText":"His purse is still on his belt, and there is silver in it. A week of people have stepped over him, and not one has taken it.","hintFor":2,"lateLine":"It takes you until full dark, but you find it."},{"id":"2-3-3","place":"the narrows where the dog lies","actions":[{"attr":"Might","verb":"hold the chain short and get past"},{"attr":"Aim","verb":"look past the dog from the rocks"}],"clueTitle":"The full pail","clueText":"Behind the dog, at the end of its chain, stands a pail of water, full and clean. There is a scrap of fresh meat beside it.","hintFor":1,"lateLine":"It takes you until full dark, but you find it."}],"meaningQuestion":"*\"Ours was the last light burning.\"* The last of what?","weekQuestion":"Why these children, and not any others?","pull":"**Where was he trying to get to? The path goes on past him, and up.**"}'::jsonb),
('dark-moon', 1, 2, 4, '{"place":"The shaft in the hillside","narrated":false,"tone":"wry","cupNight":false,"opener":"Sit down before you fall down.","forkA":"Now they''ll hurry.","forkB":"They won''t change a thing for us.","callback":"Yesterday a branch swung on the slope with no wind. Today they knew you were at the shaft.","nudge":"{friend:Charm}, the voices below all said the same words. What were they getting ready?","riddle":{"q":"What can fill a cave and weigh nothing?","a":"light","quip":"Bring a lantern. Bring two.","accept":["light"],"maxTries":3},"leads":[{"id":"2-4-1","place":"the foot of the shaft","actions":[{"attr":"Aim","verb":"look down past the edge"},{"attr":"Agility","verb":"creep back to the lip and look"}],"clueTitle":"The second lamp","clueText":"A second lamp stands lit at the foot of the shaft, filled and trimmed, the same make as the ring in the chamber. Nobody grabbed it in a hurry.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-2","place":"the timbers at the shaft''s mouth","actions":[{"attr":"Craft","verb":"look over the timbering at the top"},{"attr":"Aim","verb":"follow the timber down by the lamplight"}],"clueTitle":"The pale scar","clueText":"On the timbering just below the top, a fresh pale scar runs down the wood, where a stone knocked loose went bouncing all the way to the bottom.","hintFor":2,"lateLine":"You almost give up. Then, at the last of the light, there it is."},{"id":"2-4-3","place":"the voices down the shaft","actions":[{"attr":"Aim","verb":"lie flat at the edge and listen"},{"attr":"Intellect","verb":"count the voices as they go round"}],"clueTitle":"The chant ran on","clueText":"When the shout went up, the heads turned, but the chant never stopped. It ran on under the shout the whole time, the same few words.","hintFor":1,"lateLine":"You almost give up. Then, at the last of the light, there it is."}],"meaningQuestion":"*\"His hand was bleeding, and he told us to sleep.\"* What did he do down there?","weekQuestion":"Why these children, and not any others?","pull":"**Is there another way into this hill, before they finish? You have tonight to find it.**"}'::jsonb),
('dark-moon', 1, 2, 5, '{"place":"The hillside by night","narrated":false,"tone":"wry","cupNight":false,"opener":"A small black circle. Somebody wanted a thing forgotten, and somebody else wouldn''t let it be.","forkA":"The king was erased by his enemies.","forkB":"The king was erased by his own people.","callback":"On Day 2 a horn button, on Day 3 a dead stranger. Tonight, a circle.","nudge":"{friend:Intellect}, who gains from a forgotten name?","riddle":{"q":"What has no beginning, no middle and no end?","a":"a circle","quip":"A small black one, this evening.","accept":["a circle","circle"],"maxTries":3},"leads":[{"id":"2-5-1","place":"the old stone where he signalled","actions":[{"attr":"Craft","verb":"run a hand over each face of it"},{"attr":"Aim","verb":"look at it side-on by the lamp"}],"clueTitle":"The ground-flat face","clueText":"On the old stone where the scout stood, one face has been ground flat, long ago. The chisel scars are weathered grey. Whatever was carved there is gone.","hintFor":2,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-2","place":"the scree below the stone","actions":[{"attr":"Agility","verb":"scramble down the scree"},{"attr":"Aim","verb":"search the scree by lamplight"}],"clueTitle":"Burned chips","clueText":"Mixed into the scree are chips of dressed stone, blackened by fire. One still carries the curve of a carved letter, broken off mid-word.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."},{"id":"2-5-3","place":"the fallen sheepfold","actions":[{"attr":"Might","verb":"lift the fallen stones one by one"},{"attr":"Craft","verb":"look at how the fold was built"}],"clueTitle":"Faces turned in","clueText":"The fold''s old cut stones were laid with their carved sides turned inward, against each other, every one. From outside, the wall shows nothing.","hintFor":1,"lateLine":"You go over the same ground twice before you see it."}],"meaningQuestion":"*\"Not one of us who would not have died for him.\"* Who was he, to the people who wrote this?","weekQuestion":"Why these children, and not any others?","pull":"**There is no second door on this hillside, and now there is a clock. Last week, six cold slivers showed you a way nobody was watching. You have five.**"}'::jsonb),
('dark-moon', 1, 2, 6, '{"place":"The lip of the shaft","narrated":false,"tone":"wry","cupNight":true,"opener":"Digging toward an older room. You have to respect the effort.","forkA":"They''re digging toward the old room to get in.","forkB":"They''re digging to find something that''s already there.","callback":"In the mine, you reached the mark after it was emptied. Tonight they''re still digging toward the older room.","nudge":"{friend:Might}, you''ve heard them digging. Cutting a way in, or searching for something?","riddle":{"q":"I have rivers with no water and cities with no houses. What am I?","a":"a map","quip":"You''re carrying one.","accept":["a map","map"],"maxTries":3},"leads":[{"id":"2-6-1","place":"the ground over the picks","actions":[{"attr":"Craft","verb":"feel the strokes through the turf"},{"attr":"Intellect","verb":"time the strokes and place them"}],"clueTitle":"One line","clueText":"The strokes come from one place only, and each new stroke lands a little nearer the old shaft than the last.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-2","place":"the two lamps at the foot","actions":[{"attr":"Aim","verb":"watch what passes the lamps"},{"attr":"Agility","verb":"crawl to the edge and look down"}],"clueTitle":"Sifted by hand","clueText":"In the lamplight at the foot of the shaft, baskets of dug earth are tipped out. Someone kneels and sifts each one through their hands before it is thrown aside.","hintFor":2,"lateLine":"By the time you find it, the fire is the only light left."},{"id":"2-6-3","place":"the hole under the old stone","actions":[{"attr":"Might","verb":"shift one more stone"},{"attr":"Agility","verb":"squeeze in to the first step"}],"clueTitle":"Your own print","clueText":"Under the stones, the first step down is thick with dust. In the dust there is no print but your own.","hintFor":1,"lateLine":"By the time you find it, the fire is the only light left."}],"meaningQuestion":"*\"Morning came. The enemy did not.\"* Where did they go?","weekQuestion":"Why these children, and not any others?","pull":"**They are digging toward the old room. Be in it first.**"}'::jsonb)
